//! 🌱️ One process-local Source owns the UI arena before serving and through its final physical retirement.
use semio_os_mcp_foundation::errors::{GatewayError,GatewayErrorCode};
use semio_framework_job::{OriginalNativeLease,OriginalTurnFailure};
use semio_framework_ui_values::{UiArenaLifetime,ui_value_arena_registry};
use semio_plugin_host::{GuestRelayAdmissionCall,GuestRelayAdmissionFailure,GuestRelayFaultHome,GuestRelayWakeDriver};
use semio_framework_value::{RetainedCloneGrant,ValueError,ValueRefusalKind};
/// 🧳️ A live process owner remains in the error until process entry chooses explicit fatal termination.
pub struct ProcessRunFailure{pub error:GatewayError,owner:Option<ProcessUiArena>}
impl From<GatewayError> for ProcessRunFailure{fn from(error:GatewayError)->Self{Self{error,owner:None}}}
impl ProcessRunFailure{pub fn with_failures_step(&mut self,mut receive:impl FnMut(&GuestRelayAdmissionFailure,&mut semio_framework_job::StepContext<'_>)->Result<(),OriginalTurnFailure>)->bool{let Some(owner)=self.owner.as_mut()else{return true};if owner.diagnostic_failure.is_some(){return false}let pending=&owner.failures;let extra=&owner.capture_failure;let leases=&mut owner.faults;let result=owner.driver.dispatch_cleanup_admission_step(false,|_,cx|GuestRelayAdmissionCall{result:(||{for index in 0..2{if let Some(failure)=pending[index].as_ref(){receive(failure,cx)?;}else if let Some(lease)=leases[index].as_mut(){if lease.terminal_is_empty(){cx.with_original_native_root_step::<GuestRelayFaultHome>(lease.recipient_identity(),|home,cx|if home.has_failure(){home.with_failure(cx,|failure,cx|receive(failure,cx))}else{Ok(())})?;}else{lease.with_native(cx,|home,cx|if home.has_failure(){home.with_failure(cx,|failure,cx|receive(failure,cx))}else{Ok(())})?;}}}if let Some(failure)=extra{receive(failure,cx)?;}Ok(())})(),execution:None});match result{Ok(ready)=>ready,Err(failure)=>{owner.diagnostic_failure=Some(failure);false}}}pub fn requires_process_exit(&self)->bool{self.owner.is_some()}pub fn exit(mut self)->!{self.with_failures_step(|failure,cx|{let mut writer=FailureWriter{cx,refusal:None};if std::fmt::write(&mut writer,format_args!("{failure:?}\n")).is_err(){return Err(writer.refusal.unwrap_or_else(||invalid("process failure diagnostic was not completely written")))}Ok(())});eprintln!("[semio-os-mcp] {:?}: {}",self.error.code,self.error.message);std::process::exit(1)}}
struct FailureWriter<'a,'cx>{cx:&'a mut semio_framework_job::StepContext<'cx>,refusal:Option<OriginalTurnFailure>}
impl std::fmt::Write for FailureWriter<'_,'_>{fn write_str(&mut self,text:&str)->std::fmt::Result{use std::io::Write;let mut bytes=text.as_bytes();while !bytes.is_empty(){let grant=self.cx.retained_grant();if self.cx.retirement_should_yield()||grant.maximum_items==0||grant.maximum_copy_bytes<bytes.len()||grant.maximum_depth==0||self.cx.fuel_remaining()<bytes.len()as u64{self.refusal=Some(invalid("process diagnostic requires its remaining funded output slice"));return Err(std::fmt::Error)}let n=match std::io::stderr().write(bytes){Ok(n)if n>0=>n,_=>{self.refusal=Some(invalid("process diagnostic stderr refused the original bytes"));return Err(std::fmt::Error)}};self.cx.consume_fuel(n as u64);if let Err(error)=self.cx.consume_retained(semio_framework_value::RetainedCloneProgress{copied_items:1,copied_bytes:n,..Default::default()}){self.refusal=Some(error.into());return Err(std::fmt::Error)}bytes=&bytes[n..];}Ok(())}}
struct ProcessUiArena{driver:GuestRelayWakeDriver,input:Option<UiArenaLifetime>,arena:Option<OriginalNativeLease<UiArenaLifetime>>,fault_inputs:[Option<GuestRelayFaultHome>;2],faults:[Option<OriginalNativeLease<GuestRelayFaultHome>>;2],failures:[Option<GuestRelayAdmissionFailure>;2],capture_failure:Option<GuestRelayAdmissionFailure>,diagnostic_failure:Option<GuestRelayAdmissionFailure>}
fn invalid(message:&'static str)->OriginalTurnFailure{ValueError::literal(ValueRefusalKind::OwnershipLimit,message).into()}
fn admits(g:RetainedCloneGrant,items:usize,d:semio_framework_value::RetirementDemand)->bool{g.maximum_items>=items&&g.maximum_copy_bytes>=d.copy_bytes&&g.maximum_capacity_bytes>=d.capacity_bytes&&g.maximum_release_bytes>=d.release_bytes&&g.maximum_depth>=d.depth}
fn error()->GatewayError{GatewayError::new(GatewayErrorCode::Internal,"process UI arena did not prove complete Source retirement; its original owners remain at process entry")}
impl ProcessUiArena{
 fn capture(&mut self,index:usize)->Result<(),GuestRelayAdmissionFailure>{while self.failures[index].is_some(){let before=self.driver.original_remaining()?;let pending=&mut self.failures[index];let fault=&mut self.faults[index];let mut captured=false;self.driver.dispatch_cleanup_admission_step(false,|_,cx|GuestRelayAdmissionCall{result:(||{let lease=fault.as_mut().ok_or_else(||invalid("process failure retains its not-yet-admitted recipient"))?;lease.with_native(cx,|home,cx|{captured=home.capture_step(pending,cx)?;Ok(())})?;Ok(())})(),execution:None})?;if !captured&&before==self.driver.original_remaining()?{return Err(invalid("process failure capture made no funded progress").into())}}Ok(())}
 fn open(&mut self,cleanup:semio_os_mcp_port::channel_port::HostOperationReserve)->Result<(),GuestRelayAdmissionFailure>{
  while self.arena.is_none()||self.faults.iter().any(Option::is_none){let before=self.driver.original_remaining()?;let input=&mut self.input;let arena=&mut self.arena;let inputs=&mut self.fault_inputs;let faults=&mut self.faults;self.driver.dispatch_admission_step(false,|_,cx|GuestRelayAdmissionCall{result:(||{if arena.is_none(){UiArenaLifetime::admit_source(input,arena,cx)?;return Ok(())}for index in 0..2{if faults[index].is_none(){cx.admit_original_native(&mut inputs[index],&mut faults[index])?;break}}Ok(())})(),execution:None})?;if before==self.driver.original_remaining()?{return Err(invalid("process native admission made no funded progress").into())}}
  let(items,opening,work)=UiArenaLifetime::opening_reserve()?;let(close_items,closure,close_work)=UiArenaLifetime::closure_reserve()?;let available=self.driver.original_remaining()?;let needed=RetainedCloneGrant{maximum_items:items.checked_add(close_items).and_then(|v|v.checked_add(cleanup.retained.maximum_items)).ok_or_else(||invalid("process item reserve overflow"))?,maximum_copy_bytes:opening.copy_bytes.checked_add(closure.copy_bytes).and_then(|v|v.checked_add(cleanup.retained.maximum_copy_bytes)).ok_or_else(||invalid("process copy reserve overflow"))?,maximum_capacity_bytes:opening.capacity_bytes.checked_add(cleanup.retained.maximum_capacity_bytes).ok_or_else(||invalid("process capacity reserve overflow"))?,maximum_release_bytes:closure.release_bytes.checked_add(cleanup.retained.maximum_release_bytes).ok_or_else(||invalid("process release reserve overflow"))?,maximum_depth:opening.depth.max(closure.depth).max(cleanup.retained.maximum_depth)};if !admits(available,needed.maximum_items,semio_framework_value::RetirementDemand{copy_bytes:needed.maximum_copy_bytes,capacity_bytes:needed.maximum_capacity_bytes,release_bytes:needed.maximum_release_bytes,depth:needed.maximum_depth})||work==0{return Err(invalid("remaining process Source cannot fund arena opening and independent arena/Root cleanup").into())}
  let total_work=work.checked_add(close_work).and_then(|v|v.checked_add(cleanup.work_fuel)).ok_or_else(||invalid("process work reserve overflow"))?;let mut checked=false;while !checked{self.driver.dispatch_admission_step(false,|_,cx|GuestRelayAdmissionCall{result:(||{if cx.original_total_fuel_remaining()<total_work||semio_framework_job::default_now_us().is_none_or(|now|now>=cx.original_absolute_deadline_us().saturating_sub(cleanup.maximum_microseconds)){return Err(invalid("actual process work/deadline cannot retain independent arena and Root cleanup"))}checked=true;Ok(())})(),execution:None})?;}
  let mut ready=false;while !ready{let before=self.driver.original_remaining()?;let arena=self.arena.as_mut().ok_or_else(||invalid("process arena lease disappeared"))?;self.driver.dispatch_admission_step(false,|_,cx|GuestRelayAdmissionCall{result:UiArenaLifetime::advance_on_source(arena,cx).map(|value|ready=value),execution:None})?;if !ready&&before==self.driver.original_remaining()?{return Err(invalid("process arena opening made no funded progress").into())}}Ok(())
 }
 fn close(&mut self)->Result<(),GuestRelayAdmissionFailure>{for index in 0..2{if self.failures[index].is_some(){self.capture(index)?}}for index in 0..3{loop{let empty=if index==0{self.arena.is_none()}else{self.faults[index-1].is_none()};if empty{break}let before=self.driver.original_remaining()?;let mut done=false;self.driver.dispatch_cleanup_admission_step(false,|_,cx|GuestRelayAdmissionCall{result:if index==0{OriginalNativeLease::return_slot_step(&mut self.arena,cx).map(|value|done=value)}else{OriginalNativeLease::return_slot_step(&mut self.faults[index-1],cx).map(|value|done=value)},execution:None})?;if !done&&before==self.driver.original_remaining()?{return Err(invalid("process arena lease return made no funded progress").into())}}}semio_framework_async::block_on(self.driver.close_operation())?;if !self.driver.operation_terminal_is_empty()?{return Err(invalid("process arena Source did not become empty").into())}Ok(())}
}
pub fn serve(policy:semio_plugin_host_wake::GuestRelayDriverPolicy,operation:semio_os_mcp_port::channel_port::HostOperationPolicy,run:impl FnOnce()->Result<(),GatewayError>)->Result<(),ProcessRunFailure>{
 let reserve=operation.cleanup;let caps=policy.operation_caps(semio_plugin_host::GuestRelayOperationReserve{retained:reserve.retained,work_fuel:reserve.work_fuel,execution_fuel:reserve.execution_fuel,maximum_microseconds:reserve.maximum_microseconds},semio_plugin_host::GuestRelayOperationTransit{retained:operation.transit.retained,work_fuel:operation.transit.work_fuel},semio_plugin_host::GuestRelayOperationInfrastructure{retained:operation.infrastructure.retained,work_fuel:operation.infrastructure.work_fuel,maximum_cleanup_microseconds:operation.infrastructure.maximum_cleanup_microseconds});let driver=caps.issue(semio_plugin_host::GuestRelayOperationRequest{work_units:policy.root.operation_fuel,maximum_elapsed_microseconds:policy.root.maximum_lifetime_microseconds,retained:policy.operation},semio_framework_job::default_now_us,Box::new(||false)).map_err(|_|ProcessRunFailure::from(error()))?;
 let mut owner=ProcessUiArena{driver,input:Some(UiArenaLifetime::new(ui_value_arena_registry())),arena:None,fault_inputs:[Some(GuestRelayFaultHome::empty()),Some(GuestRelayFaultHome::empty())],faults:[None,None],failures:[None,None],capture_failure:None,diagnostic_failure:None};let result=match owner.open(reserve){Ok(())=>run(),Err(failure)=>{owner.failures[0]=Some(failure);Err(error())}};match owner.close(){Ok(())=>result.map_err(Into::into),Err(failure)=>{owner.failures[1]=Some(failure);if let Err(failure)=owner.capture(1){owner.capture_failure=Some(failure)}Err(ProcessRunFailure{error:result.err().unwrap_or_else(error),owner:Some(owner)})}}
}

#[cfg(test)]mod tests{use super::*;#[test]fn process_arena_returns_normally_only_after_real_source_empty(){if let Ok(mode)=std::env::var("SEMIO_MCP_PROCESS_ARENA_CHILD"){let policy=serde_json::from_str(include_str!("../🎚️config/🏛️host-driver-policy.json")).unwrap();let operation=serde_json::from_str(include_str!("../🎚️config/💡️host-operation-policy.json")).unwrap();let mut held=None;let result=serve(policy,operation,||{assert!(ui_value_arena_registry().borrow().unwrap().is_some());if mode=="blocked"{held=ui_value_arena_registry().borrow().unwrap();}eprintln!("[DEBUG] process-arena-child-ready");Ok(())});match result{Ok(())=>{assert_eq!(mode,"normal");assert!(ui_value_arena_registry().borrow().is_err())},Err(failure)=>{assert!(failure.requires_process_exit());failure.exit()}}return}let law:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/🔣️.json")).unwrap();for row in law["cases"].as_array().unwrap(){let output=std::process::Command::new(std::env::current_exe().unwrap()).args(["--exact","tests::process_arena_returns_normally_only_after_real_source_empty","--nocapture"]).env("SEMIO_MCP_PROCESS_ARENA_CHILD",row["mode"].as_str().unwrap()).output().unwrap();assert_eq!(output.status.code(),Some(row["exitCode"].as_i64().unwrap()as i32));assert!(String::from_utf8_lossy(&output.stderr).contains("[DEBUG] process-arena-child-ready"));}}}
